import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"37、【家人】 離下巽上","description":"溫公易說 - 37、【家人】 離下巽上","frontmatter":{"title":"37、【家人】 離下巽上","description":"溫公易說 - 37、【家人】 離下巽上"},"headers":[],"relativePath":"classics/wengong/038.md","filePath":"classics/wengong/038.md"}'),l={name:"classics/wengong/038.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_37、【家人】-離下巽上" tabindex="-1">37、【家人】 離下巽上 <a class="header-anchor" href="#_37、【家人】-離下巽上" aria-label="Permalink to “37、【家人】 離下巽上”">​</a></h1><h3 id="彖曰-家人-女正位乎內-男正位乎外-男女正-天地之大義也。家人有嚴君焉-父母之謂也。父父子子-兄兄弟弟-夫夫婦婦-而家道正。正家而天下定矣。" tabindex="-1">彖曰：家人，女正位乎內，男正位乎外，男女正，天地之大義也。家人有嚴君焉，父母之謂也。父父子子，兄兄弟弟，夫夫婦婦，而家道正。正家而天下定矣。 <a class="header-anchor" href="#彖曰-家人-女正位乎內-男正位乎外-男女正-天地之大義也。家人有嚴君焉-父母之謂也。父父子子-兄兄弟弟-夫夫婦婦-而家道正。正家而天下定矣。" aria-label="Permalink to “彖曰：家人，女正位乎內，男正位乎外，男女正，天地之大義也。家人有嚴君焉，父母之謂也。父父子子，兄兄弟弟，夫夫婦婦，而家道正。正家而天下定矣。”">​</a></h3><p>家者，治之至小者也，然有嚴君之道焉，嚴恭也。知事親則知事君矣。</p><h3 id="象曰-風自火出-家人。君子以言有物而行有恆。" tabindex="-1">象曰：風自火出，家人。君子以言有物而行有恆。 <a class="header-anchor" href="#象曰-風自火出-家人。君子以言有物而行有恆。" aria-label="Permalink to “象曰：風自火出，家人。君子以言有物而行有恆。”">​</a></h3><h3 id="初九-閒有家-悔亡-象曰-閒有家-志未變也。" tabindex="-1">初九：閒有家，悔亡 象曰：閒有家，志未變也。 <a class="header-anchor" href="#初九-閒有家-悔亡-象曰-閒有家-志未變也。" aria-label="Permalink to “初九：閒有家，悔亡 象曰：閒有家，志未變也。”">​</a></h3><h3 id="六二-無攸遂-在中饋-貞吉-象曰-六二之吉-順以巽也。" tabindex="-1">六二：無攸遂，在中饋，貞吉 象曰：六二之吉，順以巽也。 <a class="header-anchor" href="#六二-無攸遂-在中饋-貞吉-象曰-六二之吉-順以巽也。" aria-label="Permalink to “六二：無攸遂，在中饋，貞吉 象曰：六二之吉，順以巽也。”">​</a></h3><h3 id="九三-家人嗃嗃-悔厲-吉-婦子嘻嘻-終吝-象曰-家人嗃嗃-未失也-婦子嘻嘻-失家節也。" tabindex="-1">九三：家人嗃嗃，悔厲，吉；婦子嘻嘻，終吝 象曰：家人嗃嗃，未失也；婦子嘻嘻，失家節也。 <a class="header-anchor" href="#九三-家人嗃嗃-悔厲-吉-婦子嘻嘻-終吝-象曰-家人嗃嗃-未失也-婦子嘻嘻-失家節也。" aria-label="Permalink to “九三：家人嗃嗃，悔厲，吉；婦子嘻嘻，終吝 象曰：家人嗃嗃，未失也；婦子嘻嘻，失家節也。”">​</a></h3><h3 id="六四-富家-大吉-象曰-富家大吉-順在位也。" tabindex="-1">六四：富家，大吉 象曰：富家大吉，順在位也。 <a class="header-anchor" href="#六四-富家-大吉-象曰-富家大吉-順在位也。" aria-label="Permalink to “六四：富家，大吉 象曰：富家大吉，順在位也。”">​</a></h3><h3 id="九五-王假有家-勿恤-吉-象曰-王假有家-交相愛也。" tabindex="-1">九五：王假有家，勿恤，吉 象曰：王假有家，交相愛也。 <a class="header-anchor" href="#九五-王假有家-勿恤-吉-象曰-王假有家-交相愛也。" aria-label="Permalink to “九五：王假有家，勿恤，吉 象曰：王假有家，交相愛也。”">​</a></h3><p>假大也。文王刑于寡妻，至於兄弟，以御於家邦。大其家以至於有天下，親其親以及人之親，長其長以及人之長。上下交相愛，而天下和矣。故曰交相愛也。</p><h3 id="上九-有孚-威如-終吉-象曰-威如之吉-反身之謂也。" tabindex="-1">上九：有孚，威如，終吉 象曰：威如之吉，反身之謂也。 <a class="header-anchor" href="#上九-有孚-威如-終吉-象曰-威如之吉-反身之謂也。" aria-label="Permalink to “上九：有孚，威如，終吉 象曰：威如之吉，反身之謂也。”">​</a></h3><p>上九以陽居上，家之至尊者也。家人望之以為表式，苟其身不正，則雖令不從。是以內盡至誠，為人所信，然後有威可畏，而獲終吉也。大學曰：欲齊其家者，先修其身；欲修其身者，先正其心；欲正其心者，先誠其意。此之謂也。</p>',12)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
